"""One-time authoring helper for the compact, version-controlled campaign scene JSON."""
import json
from pathlib import Path

ROOT = Path(__file__).parents[1] / "content" / "macbeth"
original = json.loads((ROOT / "scenes.json").read_text(encoding="utf-8"))
scenes = []

def add(cid, title, protagonist, people, summary, opening, decisions, *, act=None, source=None, ending=None):
    choices = []
    for suffix, label, destination, flags, changes, facts in decisions:
        knowledge_grants = facts or {}
        relationships = []
        if protagonist == "lady_macbeth" and suffix in {"caution", "ambition", "oppose", "prepare", "confront", "protect", "separate"}:
            relationships = [{"character_id": "macbeth", "trust": 8 if suffix in {"caution", "oppose", "confront"} else 2,
                              "hostility": 8 if suffix in {"confront", "separate"} else 0}]
        elif protagonist == "banquo" and suffix in {"trust", "challenge", "warn", "escape", "sacrifice", "fight"}:
            relationships = [{"character_id": "macbeth", "trust": 8 if suffix == "trust" else 0,
                              "hostility": 12 if suffix in {"challenge", "warn"} else 0}]
        elif protagonist == "macduff" and suffix in {"family", "warn", "evacuate", "hide", "depart", "justice", "revenge", "terms"}:
            target = "malcolm" if suffix in {"justice", "revenge", "terms"} else "lady_macduff"
            relationships = [{"character_id": target, "trust": 10 if suffix not in {"depart", "revenge"} else 0,
                              "hostility": 12 if suffix == "depart" else 0}]
        if protagonist == "macduff" and suffix in {"evacuate", "hide", "depart"}:
            safe = suffix != "depart"
            changes = {**changes, "lady_macduff": {"alive": safe}, "macduff_child": {"alive": safe}}
            knowledge_grants = {"macduff": (facts or {}).get("macduff", []),
                                "lady_macduff": ["family_safe" if safe else "family_left_behind"],
                                "macduff_child": ["family_safe" if safe else "family_left_behind"]}
        if protagonist == "lady_macbeth" and suffix in {"conceal", "reveal"}:
            changes = {**changes, "duncan": {"alive": False}}
        choices.append({"choice_id": f"{protagonist}_{suffix}", "action_id": f"{protagonist}_{suffix}",
            "description": label, "actor_id": None, "prerequisites": [], "state_flags": flags,
            "next_scene_id": destination, "conditions": {}, "character_changes": changes,
            "relationship_changes": relationships, "grants_knowledge": [], "knowledge_grants": knowledge_grants})
    scenes.append({"scene_id": cid, "title": title, "location": people.get("location", "Scotland"),
        "canonical_reference": source, "source_classification": "alternate_history" if not source else "canonical_adaptation",
        "source_act_id": act, "source_scene_id": None, "participants": people["cast"], "summary": summary,
        "opening_narration": opening, "available_choices": choices, "is_ending": ending is not None, "ending_id": ending})

def cast(location, *ids): return {"location": location, "cast": list(ids)}
def d(suffix, label, dest, flag, who, delta, facts):
    return (suffix, label, dest, {flag: True}, {who: delta}, {who: facts} if facts else {})

