add("lady_letter", "The Letter at Inverness", "lady_macbeth", L, "A letter brings the witches’ promise to Inverness. Lady Macbeth chooses what power should mean.", "I read my husband’s letter twice. Its promise sounds like a door opening; I must decide whether to urge him through it.", [d("caution", "Counsel patience and a lawful rise.", "lady_duncan", "lady_counselled_caution", "lady_macbeth", {"resolve": 56, "influence": 40}, ["received_macbeth_letter", "urged_caution"]), d("ambition", "Urge Macbeth to help fate with deliberate action.", "lady_duncan", "lady_counselled_ambition", "lady_macbeth", {"ambition": 70, "influence": 70}, ["received_macbeth_letter", "urged_ambition"])], act="act_1", source="Macbeth, Act 1, Scene 5")
add("lady_duncan", "A King Under My Roof", "lady_macbeth", L, "Duncan arrives as an honored guest. Lady Macbeth can strengthen Macbeth’s resolve or prevent the household from crossing a line.", "Duncan thanks me for my welcome. Behind the courtesy, I see Macbeth weighing the crown against the man who trusts us.", [d("oppose", "Tell Macbeth Duncan’s trust makes murder indefensible.", "lady_night", "lady_opposed_regicide", "lady_macbeth", {"morality": 70, "resolve": 35}, ["duncan_is_guest", "opposed_regicide"]), d("prepare", "Take command of the plan and prepare the guards’ drink.", "lady_night", "lady_enabled_regicide", "lady_macbeth", {"influence": 85, "resolve": 75}, ["duncan_is_guest", "prepared_regicide"])], act="act_1", source="Macbeth, Act 1, Scene 6")
add("lady_night", "The Night of the Deed", "lady_macbeth", L, "Macbeth returns from Duncan’s chamber. Lady Macbeth may conceal the murder, expose it, or stop it before it happens.", "A cry breaks the night. Macbeth stands before me with the daggers. I can still choose what happens next.", [d("conceal", "Conceal the deed and direct suspicion at the guards.", "lady_queen", "duncan_murdered", "lady_macbeth", {"guilt": 80, "emotional_stability": 35, "influence": 90}, ["duncan_murdered", "covered_evidence"]), d("reveal", "Call witnesses and reveal the deed before the household settles.", "lady_queen", "lady_revealed_regicide", "lady_macbeth", {"guilt": 45, "morality": 70}, ["revealed_regicide"]), d("stop", "Wake the household and prevent Duncan’s murder.", "lady_spared", "duncan_spared", "lady_macbeth", {"resolve": 80}, ["duncan_spared"])], act="act_2", source="Macbeth, Act 2, Scene 2")
