add("lady_queen", "The Crown and the Distance", "lady_macbeth", L, "As queen, Lady Macbeth finds influence cannot command affection. She may confront Macbeth, protect him, or seek separation.", "The crown is mine to wear, yet every corridor feels farther from Macbeth. The court watches us for weakness.", [d("confront", "Challenge Macbeth’s violence and demand he stop ruling by fear.", "lady_crisis", "lady_confronted", "lady_macbeth", {"resolve": 70, "isolation": 35}, ["confronted_macbeth"]), d("protect", "Conceal his instability and preserve your influence.", "lady_crisis", "lady_protected", "lady_macbeth", {"influence": 90, "isolation": 70, "guilt": 60}, ["protected_macbeth"]), d("separate", "Seek safety and a negotiated separation.", "lady_crisis", "lady_separation", "lady_macbeth", {"resolve": 75, "isolation": 5, "influence": 30}, ["sought_separation"])], act="act_3", source="Macbeth, Act 3, Scene 4")
for choice in scenes[-1]["available_choices"]: choice["next_scene_id"] = "lady_banquet"
add("lady_banquet", "The Banquet and the Plot", "lady_macbeth", cast("Forres, the royal hall", "lady_macbeth", "macbeth", "banquo", "fleance"), "Macbeth’s fear turns toward Banquo. Lady Macbeth can enable the murder, warn Banquo and Fleance, or compel Macbeth to spare his friend.", "The banquet is being prepared. Macbeth’s servants await an order concerning Banquo, and I can still shape what happens next.", [d("betray_banquo", "Permit the plot against Banquo and keep the court quiet.", "lady_ghost", "banquo_murdered", "lady_macbeth", {"guilt": 82, "emotional_stability": 40}, ["authorized_banquo_plot"]), d("warn_banquo", "Warn Banquo and Fleance before the killers reach them.", "lady_crisis", "banquo_escaped", "lady_macbeth", {"resolve": 75, "influence": 65}, ["warned_banquo_and_fleance"]), d("spare_banquo", "Confront Macbeth and insist Banquo be spared.", "lady_crisis", "banquo_spared", "lady_macbeth", {"resolve": 78, "influence": 60}, ["intervened_for_banquo"])], act="act_3", source="Macbeth, Act 3, Scene 4")
