add("lady_ghost", "A Living Witness at the Feast", "lady_macbeth", cast("Forres, the royal hall", "lady_macbeth", "macbeth", "banquo"), "After Lady Macbeth enabled Banquo’s murder, his ghost appears at the banquet. She can shield Macbeth or name what the court sees.", "Macbeth stares at a place no living guest occupies. I know why Banquo is absent, and the court is beginning to ask.", [d("shield_macbeth", "Dismiss the king’s terror and send the witnesses away.", "lady_crisis", "lady_shielded_ghost", "lady_macbeth", {"guilt": 92, "influence": 75}, ["concealed_banquos_ghost"]), d("name_ghost", "Acknowledge Banquo’s murder and confront Macbeth in public.", "lady_crisis", "lady_named_ghost", "lady_macbeth", {"guilt": 88, "resolve": 82}, ["named_banquos_ghost"])], act="act_3", source="Macbeth, Act 3, Scene 4")
