for cid,title,summary,eid,opening in [("lady_spared","The Crown Refused","Duncan lives; Lady Macbeth prevented a crime that would bind her future to blood.","lady_duncan_spared","I chose the king’s life over the crown. The danger remains, but this night does not become our secret."),("lady_confession","A Truth Spoken","Lady Macbeth accepts responsibility and gives Scotland evidence to judge her.","lady_confession","My confession cannot undo the dead. It can end the lie that my hands were clean."),("lady_reconciliation","A Narrow Truce","Lady Macbeth and Macbeth reckon honestly and negotiate an end to their rule.","lady_reconciliation","We meet without courtiers between us. At last neither of us has to pretend."),("lady_survival","Beyond the Castle","Lady Macbeth survives the regime’s fall and begins a life apart from its power.","lady_survival","I leave the castle alive, carrying what I did and the chance to answer for it.")]: add(cid,title,"lady_macbeth",L,summary,opening,[],ending=eid)

