add("banquo_ambush","The Road at Dusk","banquo",cast("A road outside Forres","banquo","fleance"),"Hired killers close around Banquo and Fleance. Banquo’s decision determines the fate of both father and son.","Hooves approach from behind. I see steel in the dusk and put myself between danger and my son.",[d("escape","Use the prepared route and escape together.","banquo_feast","banquo_survived","banquo",{"alive":True,"resolve":62},["escaped_assassins"]),d("sacrifice","Hold the attackers while Fleance escapes alone.","banquo_lineage","banquo_died","banquo",{"alive":False,"resolve":60},["died_protecting_fleance"]),d("fight","Fight to survive and keep Fleance beside you.","banquo_feast","fleance_stayed","banquo",{"resolve":65,"suspicion":15},["fought_assassins"])],act="act_3",source="Macbeth, Act 3, Scene 3")
